// 政权几何写法：'CN' 国家；'CN.Hebei' 省级单位；'-X' 扣除；{m:'单位',p:多边形} 取交；{p:多边形} 手绘区（与陆地求交）；{p,neg:true} 扣除手绘区
const T = require('./time.js').T;
const circ = (x, y, r, n) => { const o = []; n = n || 14; for (let i = 0; i < n; i++) { const a = i / n * Math.PI * 2; o.push([+(x + r * Math.cos(a) / Math.cos(y * Math.PI / 180)).toFixed(3), +(y + r * Math.sin(a)).toFixed(3)]); } return o; };
const hole = (x, y, r) => ({ p: circ(x, y, r), neg: true, raw: true });
const box = (x0, y0, x1, y1) => [[x0, y0], [x1, y0], [x1, y1], [x0, y1]];

